#include "sim/typed/room_match_control.h"
#include "sim/typed/command_codec.h"
#include <algorithm>
namespace pvz::typed72 {
std::optional<Seat> RoomMatchControl::side_for(const std::string& peer)const{for(const auto& m:state_.members)if(m.peer==peer)return m.seat;return {};}
bool RoomMatchControl::connected(const std::string& peer)const{for(const auto& m:state_.members)if(m.peer==peer&&m.connected)return true;return std::find(state_.spectators.begin(),state_.spectators.end(),peer)!=state_.spectators.end();}
bool RoomMatchControl::all_connected()const{return std::all_of(state_.members.begin(),state_.members.end(),[](const auto& m){return m.connected;});}
bool RoomMatchControl::vacant(Seat seat)const{return std::none_of(state_.members.begin(),state_.members.end(),[&](const auto& m){return m.seat==seat;});}
Seat RoomMatchControl::free_seat()const{for(const auto s:state_.seats())if(vacant(s))return s;throw std::logic_error("no free room seat");}
std::vector<std::string> RoomMatchControl::snapshot_peers()const{std::vector<std::string> peers;for(const auto& m:state_.members)if(m.peer!="host"&&!state_.ai_peers.contains(m.peer)&&m.connected)peers.push_back(m.peer);for(const auto& p:state_.spectators)if(p!="host")peers.push_back(p);return peers;}
std::string RoomMatchControl::audit_error()const{if(!state_.audit_error.empty())return state_.audit_error;auto error=services_.journal_error();if(!error.empty())return error;return battle_?battle_->state.audit_error:std::string{};}
void RoomMatchControl::clear(Seat seat){if(battle_)battle_->input.clear(seat);}
std::string RoomMatchControl::halt_for_audit(const std::string& error){if(state_.audit_error==error&&state_.paused)return error;state_.audit_error=error;state_.paused=true;state_.accumulator=0.;state_.status=error;++state_.revision;if(battle_)for(const auto seat:state_.seats())clear(seat);return error;}
std::string RoomMatchControl::record(RoomMembershipEvent event){try{services_.record(event);}catch(const ReplayJournalError& e){return halt_for_audit(e.what());}return {};}
void RoomMatchControl::forget(std::optional<Seat> seat){if(!seat)return;state_.confirmed.fill(false);state_.ready.fill(false);if(state_.scripted()&&state_.pve_day)services_.forget_seat_deck(*seat);}
void RoomMatchControl::reset_selection(){services_.save_replay();if(battle_)services_.close_battle();battle_=nullptr;services_.reset_draft_fields();state_.ready.fill(false);state_.confirmed.fill(false);state_.loaded.fill(false);state_.phase=RoomPhase::config;state_.deadline=0.;state_.result.reset();state_.accumulator=0.;state_.rematch_votes.clear();state_.pause_votes.clear();state_.paused=false;state_.restart_votes.clear();++state_.revision;state_.loading_id.reset();state_.same_deck_rematch=false;}
bool RoomMatchControl::erase_spectator(const std::string& peer){auto it=std::find(state_.spectators.begin(),state_.spectators.end(),peer);if(it==state_.spectators.end())return false;state_.spectators.erase(it);services_.drop_progress_peer(peer);return true;}
void RoomMatchControl::release(const std::string& peer,std::string status){forget(side_for(peer));std::erase_if(state_.members,[&](const auto& m){return m.peer==peer;});services_.drop_progress_peer(peer);services_.sync_progress();state_.ai_peers.erase(peer);state_.subsidy_peers.erase(peer);services_.drop_config_request(peer);state_.rematch_votes.clear();state_.pause_votes.clear();state_.paused=false;state_.restart_votes.clear();if(all_connected())state_.disconnect_deadline.reset();state_.status=std::move(status);++state_.revision;}
std::string RoomMatchControl::connect(const std::string& peer,bool spectator,std::optional<Seat> seat){const bool watching=std::find(state_.spectators.begin(),state_.spectators.end(),peer)!=state_.spectators.end();if(spectator){if(!state_.allow_spectators)return "房主已关闭观战";if(side_for(peer))return "身份已占用";const auto count=std::count_if(state_.spectators.begin(),state_.spectators.end(),[](const auto& p){return p!="host";});if(!watching&&size_t(count)>=state_.max_spectators)return "观战人数已满";if(!watching)state_.spectators.push_back(peer);return {};}
    if(watching)return "观众不能占用玩家席位";if(const auto error=audit_error();!error.empty())return halt_for_audit(error);if(peer=="host")return "身份已占用";for(auto& m:state_.members)if(m.peer==peer){m.connected=true;if(all_connected())state_.disconnect_deadline.reset();state_.status="对方已重连";return record({RoomMembershipEventKind::reconnected,peer});}
    if(state_.members.size()>=state_.seats().size())return "房间已满";if(state_.phase!=RoomPhase::config&&state_.phase!=RoomPhase::result)return "对局中不能加入玩家席位";if(seat&&std::find(state_.seats().begin(),state_.seats().end(),*seat)==state_.seats().end())return "席位设置无效";if(seat&&!vacant(*seat))return "该席位已有玩家";if(state_.phase==RoomPhase::result)reset_selection();const auto chosen=seat.value_or(free_seat());forget(chosen);state_.members.push_back({peer,chosen,true});++state_.revision;services_.sync_progress();const auto error=record({RoomMembershipEventKind::joined,peer});if(!error.empty())return error;state_.status="双方确认地图后开始禁选";return {};}
std::string RoomMatchControl::role_change_error(const std::string& peer,bool spectator,std::optional<Seat> seat)const{if(!connected(peer))return "玩家未连接";if(state_.phase!=RoomPhase::config&&state_.phase!=RoomPhase::result)return "请在房间准备阶段或对局结束后切换身份";const bool watching=std::find(state_.spectators.begin(),state_.spectators.end(),peer)!=state_.spectators.end();if(spectator){if(watching)return {};if(peer!="host"&&!state_.allow_spectators)return "房主已关闭观战";if(peer!="host"&&size_t(std::count_if(state_.spectators.begin(),state_.spectators.end(),[](const auto& p){return p!="host";}))>=state_.max_spectators)return "观战人数已满";}else{if(!watching)return "已经在玩家席位";if(std::none_of(state_.seats().begin(),state_.seats().end(),[&](Seat s){return vacant(s);}))return "玩家席位已满";if(seat&&std::find(state_.seats().begin(),state_.seats().end(),*seat)==state_.seats().end())return "阵营设置无效";if(seat&&!vacant(*seat))return "该阵营已有玩家";}return {};}
std::string RoomMatchControl::change_role(const std::string& peer,bool spectator,std::optional<Seat> seat){const auto error=role_change_error(peer,spectator,seat);if(!error.empty())return error;if(spectator&&std::find(state_.spectators.begin(),state_.spectators.end(),peer)!=state_.spectators.end())return {};if(!spectator&&!seat)seat=free_seat();forget(spectator?side_for(peer):seat);reset_selection();state_.disconnect_deadline.reset();if(spectator){std::erase_if(state_.members,[&](const auto& m){return m.peer==peer;});state_.spectators.push_back(peer);}else{std::erase(state_.spectators,peer);state_.members.push_back({peer,*seat,true});}services_.sync_progress();state_.status="席位已变更，请双方重新确认地图";return record({RoomMembershipEventKind::role_changed,peer,spectator?std::nullopt:seat,spectator});}
void RoomMatchControl::capture_result(){if(!audit_error().empty()||state_.result||!battle_||!battle_->state.result)return;const auto& r=*battle_->state.result;state_.result=RoomSettlement{r.winner,r.reason==RoomResultReason::hero_death?RoomSettlementReason::hero_death:r.reason==RoomResultReason::waves_cleared?RoomSettlementReason::waves_cleared:RoomSettlementReason::surrender,r.tick,{}, {},r.coins,r.fallen};state_.phase=RoomPhase::result;++state_.revision;if(state_.scripted()&&state_.pve_day){state_.result->pve_day=state_.pve_day;services_.finish_progress(*state_.result);}state_.status="对局结束";state_.disconnect_deadline.reset();RoomMembershipEvent event{RoomMembershipEventKind::result};event.result=state_.result;record(event);services_.save_replay();}
void RoomMatchControl::forfeit(const std::string& peer,RoomSettlementReason reason){const auto seat=side_for(peer);if(!seat||std::find(state_.seats().begin(),state_.seats().end(),*seat)==state_.seats().end())return;const Seat side=team_of(*seat)==Seat::plant?Seat::plant:Seat::zombie;state_.result=RoomSettlement{side==Seat::plant?RoomWinner::zombie:RoomWinner::plant,reason,tick(),side};state_.phase=RoomPhase::result;state_.status="对方退出对局，判负";state_.disconnect_deadline.reset();state_.paused=false;state_.pause_votes.clear();++state_.revision;RoomMembershipEvent event{RoomMembershipEventKind::forfeit,peer,side};event.reason=reason;event.result=state_.result;record(event);services_.save_replay();}
void RoomMatchControl::disconnect(const std::string& peer){if(erase_spectator(peer))return;auto found=std::find_if(state_.members.begin(),state_.members.end(),[&](const auto& m){return m.peer==peer;});if(found==state_.members.end())return;found->connected=false;if(const auto error=audit_error();!error.empty()){halt_for_audit(error);return;}clear(found->seat);capture_result();if(state_.result){record({RoomMembershipEventKind::disconnected_after_result,peer});if(peer!="host")release(peer,"对方已离开，已确定的对局结果保留；可邀请新玩家加入");else{state_.disconnect_deadline.reset();state_.status="对方已离开，已确定的对局结果保留";++state_.revision;}return;}if(state_.phase==RoomPhase::config&&peer!="host"){record({RoomMembershipEventKind::left,peer});reset_selection();release(peer,"对方已离开房间；可邀请新玩家加入");return;}state_.disconnect_deadline=state_.clock+20.;state_.status="对方断线，等待重连（20 秒）";record({RoomMembershipEventKind::disconnected,peer});}
void RoomMatchControl::leave(const std::string& peer){if(erase_spectator(peer))return;if(!side_for(peer)||peer=="host")return;if(const auto error=audit_error();!error.empty()){halt_for_audit(error);return;}for(auto& m:state_.members)if(m.peer==peer)m.connected=false;capture_result();if(!state_.result&&state_.phase==RoomPhase::battle)forfeit(peer,RoomSettlementReason::leave);else if(!state_.result&&state_.phase==RoomPhase::loading){state_.result=RoomSettlement{{},RoomSettlementReason::leave,tick()};state_.phase=RoomPhase::result;RoomMembershipEvent event{RoomMembershipEventKind::interrupted};event.reason=RoomSettlementReason::leave;record(event);}record({RoomMembershipEventKind::left,peer});if(state_.phase==RoomPhase::config||state_.phase==RoomPhase::banning||state_.phase==RoomPhase::picking)reset_selection();const bool lost=state_.result&&state_.result->forfeit==side_for(peer);release(peer,lost?"对方退出对局，判对方负；可邀请新玩家加入":"对方已离开房间；可邀请新玩家加入");}
void RoomMatchControl::kick(const std::string& peer){if(erase_spectator(peer))return;if(!side_for(peer)||peer=="host")return;if(const auto error=audit_error();!error.empty()){halt_for_audit(error);return;}for(auto& m:state_.members)if(m.peer==peer)m.connected=false;capture_result();if(!state_.result&&(state_.phase==RoomPhase::loading||state_.phase==RoomPhase::battle)){state_.result=RoomSettlement{{},RoomSettlementReason::kick,tick()};state_.phase=RoomPhase::result;RoomMembershipEvent event{RoomMembershipEventKind::interrupted};event.reason=RoomSettlementReason::kick;record(event);}record({RoomMembershipEventKind::kicked,peer});release(peer,"已请出对方；可邀请新玩家加入");}
void RoomMatchControl::host_quit(){if(!audit_error().empty())return;capture_result();if(!state_.result&&state_.phase==RoomPhase::battle){if(side_for("host"))forfeit("host",RoomSettlementReason::leave);else{state_.result=RoomSettlement{{},RoomSettlementReason::host_closed,tick()};state_.phase=RoomPhase::result;state_.status="房主关闭房间，对局中止";++state_.revision;RoomMembershipEvent event{RoomMembershipEventKind::interrupted};event.reason=RoomSettlementReason::host_closed;record(event);services_.save_replay();}}}
std::string RoomMatchControl::reopen(){if(state_.phase!=RoomPhase::result)return "对局尚未结束";if(state_.members.size()>=state_.seats().size())return "对方仍在房间中";reset_selection();state_.status="等待对方加入并确认地图";return {};}
std::string RoomMatchControl::input(const std::string& peer,const WireObject& raw){if(!connected(peer))return "玩家未连接";const auto side=side_for(peer);if(!side)return "观众不能操作对局";if(const auto error=audit_error();!error.empty())return halt_for_audit(error);if(state_.phase!=RoomPhase::battle||!battle_)return "当前不在战斗";const auto attempt=decode_command(raw);const bool terminal=std::holds_alternative<SurrenderCommand>(attempt.payload);if((state_.paused||state_.disconnect_deadline)&&!terminal)return "对局暂停";std::string error;try{error=battle_->input.raw(*side,raw,attempt);}catch(const ReplayJournalError& e){return halt_for_audit(e.what());}capture_result();const auto audit=audit_error();return audit.empty()?error:halt_for_audit(audit);}
std::string RoomMatchControl::pause(const std::string& peer,const InputField<int64_t>& epoch,const InputField<bool>& desired,const InputField<bool>& cancel){const auto side=side_for(peer);if(!connected(peer))return "玩家未连接";if(!side)return "观众不能操作对局";if(state_.phase!=RoomPhase::battle)return "当前没有战斗";if(!epoch.absent()&&(!epoch.valid()||epoch.value!=int64_t(state_.pause_epoch)))return "暂停状态已变化，请使用最新房间状态";if((!desired.absent()&&!desired.valid())||(!cancel.absent()&&!cancel.valid()))return "暂停请求无效";if(cancel.valid()&&cancel.value){if(!state_.paused)state_.pause_votes.erase(*side);}else if(desired.valid()?desired.value:!state_.paused){if(state_.paused)return {};state_.pause_votes.insert(*side);if(std::all_of(state_.seats().begin(),state_.seats().end(),[&](Seat s){return state_.pause_votes.contains(s);})){state_.paused=true;state_.accumulator=0.;for(const auto seat:state_.seats())clear(seat);}}else{if(!state_.paused)return {};state_.paused=false;state_.pause_votes.clear();++state_.pause_epoch;state_.accumulator=0.;}state_.status=state_.paused?"全体玩家已同意暂停":!state_.pause_votes.empty()?"已请求暂停 "+std::to_string(state_.pause_votes.size())+"/"+std::to_string(state_.seats().size())+"，等待其他玩家确认":"对局继续";++state_.revision;return {};}
std::string RoomMatchControl::loaded(const std::string& peer,const std::optional<std::string>& id,const std::optional<std::string>& hash){if(!connected(peer))return "玩家未连接";const auto side=side_for(peer);if(!side)return "观众不能操作对局";if(state_.phase!=RoomPhase::loading)return "当前不在载入阶段";if(id!=state_.loading_id)return "载入确认属于旧对局，请重新同步";if(!hash||*hash!=state_.terrain_hash)return "载入地形校验不一致";state_.loaded[seat_index(*side)]=true;if(std::all_of(state_.seats().begin(),state_.seats().end(),[&](Seat s){return state_.loaded[seat_index(s)];})){state_.phase=RoomPhase::battle;state_.deadline=state_.accumulator=0.;++state_.revision;++state_.match_number;state_.status="双方载入完成，战斗开始";RoomMembershipEvent event{RoomMembershipEventKind::battle};event.match_number=state_.match_number;record(event);}return {};}
void RoomMatchControl::update(double dt){if(const auto error=audit_error();!error.empty()){if(state_.audit_error.empty())halt_for_audit(error);return;}if(dt<0.||dt>2.)return;state_.clock+=dt;if(state_.disconnect_deadline){if(state_.clock>=*state_.disconnect_deadline){std::optional<std::string> gone;for(const auto& m:state_.members)if(m.peer!="host"&&!m.connected){gone=m.peer;break;}capture_result();if(!state_.result&&state_.phase==RoomPhase::battle&&gone)forfeit(*gone,RoomSettlementReason::disconnect);else if(!state_.result){state_.result=RoomSettlement{{},RoomSettlementReason::disconnect,tick()};state_.phase=RoomPhase::result;state_.disconnect_deadline.reset();state_.status="重连超时，对局中止";++state_.revision;RoomMembershipEvent event{RoomMembershipEventKind::interrupted};event.reason=RoomSettlementReason::disconnect;record(event);}state_.disconnect_deadline.reset();if(gone)release(*gone,state_.result&&state_.result->forfeit?"对方断线未重连，判对方负；可邀请新玩家加入":"重连超时，对局中止；可邀请新玩家加入");}return;}if(!all_connected()||state_.members.size()<state_.seats().size())return;if((state_.phase==RoomPhase::banning||state_.phase==RoomPhase::picking)&&state_.clock>=state_.deadline)services_.draft_timeout();else if(state_.phase==RoomPhase::loading&&state_.clock>=state_.deadline){state_.result=RoomSettlement{{},RoomSettlementReason::load_timeout,0};state_.phase=RoomPhase::result;++state_.revision;state_.status="载入超时，对局尚未开始";RoomMembershipEvent event{RoomMembershipEventKind::interrupted};event.reason=RoomSettlementReason::load_timeout;record(event);}else if(state_.phase==RoomPhase::battle&&!state_.paused){if(!battle_)throw std::logic_error("battle phase requires a typed battle");if(paced_!=battle_){pacing_={};paced_=battle_;}state_.accumulator+=dt*pacing_.scale;const int64_t count=std::min<int64_t>(12,int64_t((state_.accumulator+1e-9)/battle_->rules.dt()));if(count){const double start=services_.monotonic_seconds();try{if(battle_->recording)battle_->recording->step(count);else battle_->scheduler.step(count);}catch(const ReplayJournalError& e){halt_for_audit(e.what());return;}state_.accumulator-=count*battle_->rules.dt();pacing_.sample(services_.monotonic_seconds()-start,count*battle_->rules.dt());}if(battle_->state.result)capture_result();}}
} // namespace pvz::typed72
